/* V233 — immersive, safe-area-aware profile photo gallery.
 *
 * Android 15/16 WebView runs edge-to-edge. env(safe-area-inset-*) is not sufficient there: the
 * native shell publishes the real system-bar insets through --gc-safe-*. The old mobile rule reset
 * the viewer padding to zero, so the Android notification icons covered the title and the navigation
 * bar covered the counter / like button. This sheet intentionally loads after redesign.css and keeps
 * the image controls inside the visual canvas instead of reserving two narrow side columns.
 */

.gc-profile-photo-viewer {
  padding: max(14px, var(--gc-safe-top)) max(14px, var(--gc-safe-right))
    max(14px, var(--gc-safe-bottom)) max(14px, var(--gc-safe-left));
}

.gc-profile-photo-panel {
  max-height: calc(100dvh - max(28px, var(--gc-safe-top)) - max(28px, var(--gc-safe-bottom)));
}

.gc-profile-photo-canvas {
  grid-template-columns: minmax(0, 1fr);
  overflow: hidden;
}

.gc-profile-photo-stage {
  width: 100%;
  height: 100%;
}

.gc-profile-photo-nav {
  position: absolute;
  top: 50%;
  z-index: 3;
  width: 44px;
  height: 44px;
  margin: 0;
  border: 1px solid rgb(255 255 255 / 14%);
  border-radius: 50%;
  background: rgb(2 9 8 / 52%);
  box-shadow: 0 8px 24px rgb(0 0 0 / 20%);
  backdrop-filter: blur(12px);
  transform: translateY(-50%);
}

.gc-profile-photo-nav.is-prev { left: 18px; }
.gc-profile-photo-nav.is-next { right: 18px; }
.gc-profile-photo-nav:hover,
.gc-profile-photo-nav:focus-visible { background: rgb(255 255 255 / 16%); }

.gc-profile-photo-bar,
.gc-profile-photo-footer {
  min-width: 0;
}

.gc-profile-photo-meta,
.gc-profile-photo-actions {
  min-width: 0;
}

.gc-profile-photo-counter,
.gc-profile-photo-current,
.gc-profile-photo-like-count {
  font-variant-numeric: tabular-nums;
}

@media (max-width: 600px) {
  .gc-profile-photo-viewer {
    place-items: stretch;
    padding: 0;
    background: #050d0b;
    backdrop-filter: none;
  }

  .gc-profile-photo-panel {
    width: 100%;
    height: 100dvh;
    max-height: 100dvh;
    border: 0;
    border-radius: 0;
    background: #07110f;
    color: #f6fbf8;
    box-shadow: none;
  }

  .gc-profile-photo-bar {
    position: relative;
    z-index: 5;
    min-height: calc(56px + var(--gc-safe-top));
    padding: calc(6px + var(--gc-safe-top)) max(10px, var(--gc-safe-right)) 6px
      max(16px, var(--gc-safe-left));
    border-bottom-color: rgb(255 255 255 / 8%);
    background: linear-gradient(180deg, rgb(3 10 9 / 98%), rgb(3 10 9 / 88%));
  }

  .gc-profile-photo-title {
    padding-inline: 2px 8px;
    color: #f6fbf8;
    font-size: 18px;
    line-height: 1.25;
  }

  .gc-profile-photo-close {
    flex: 0 0 44px;
    width: 44px;
    height: 44px;
    border: 1px solid rgb(255 255 255 / 10%);
    border-radius: 50%;
    background: rgb(255 255 255 / 7%);
    color: #f6fbf8;
  }

  .gc-profile-photo-canvas {
    min-height: 0;
    padding: 0;
    background: radial-gradient(circle at 50% 42%, rgb(24 59 48 / 52%), rgb(3 9 9 / 98%) 68%);
  }

  .gc-profile-photo-stage {
    min-height: 0;
    border-radius: 0;
    background: transparent;
  }

  .gc-profile-photo-stage .gc-avatar-photo {
    max-width: 100%;
    max-height: 100%;
    border-radius: 0;
    object-fit: contain;
  }

  .gc-profile-photo-nav {
    width: 42px;
    height: 42px;
    color: #fff;
    opacity: .92;
  }

  .gc-profile-photo-nav.is-prev {
    left: max(10px, var(--gc-safe-left));
  }

  .gc-profile-photo-nav.is-next {
    right: max(10px, var(--gc-safe-right));
  }

  .gc-profile-photo-status {
    min-height: 0;
    padding: 6px max(16px, var(--gc-safe-right)) 6px max(16px, var(--gc-safe-left));
    background: #07110f;
    color: rgb(235 247 241 / 72%);
  }

  .gc-profile-photo-footer {
    grid-template-columns: minmax(0, 1fr) max-content;
    gap: 10px;
    min-height: calc(68px + var(--gc-safe-bottom));
    padding: 10px max(12px, var(--gc-safe-right)) calc(10px + var(--gc-safe-bottom))
      max(16px, var(--gc-safe-left));
    border-top-color: rgb(255 255 255 / 8%);
    background: rgb(4 12 10 / 98%);
  }

  .gc-profile-photo-meta {
    flex-wrap: wrap;
    gap: 6px 8px;
  }

  .gc-profile-photo-counter {
    color: rgb(235 247 241 / 72%);
    font-size: 15px;
    white-space: nowrap;
  }

  .gc-profile-photo-current {
    max-width: 100%;
    overflow: hidden;
    background: rgb(34 201 112 / 16%);
    color: #65e5a2;
    text-overflow: ellipsis;
  }

  .gc-profile-photo-dots { display: none; }

  .gc-profile-photo-actions {
    justify-self: end;
    gap: 7px;
  }

  .gc-profile-photo-like,
  .gc-profile-photo-delete {
    min-height: 44px;
    border-color: rgb(255 255 255 / 12%);
    border-radius: var(--gc-radius);
    background: rgb(255 255 255 / 7%);
    color: #f6fbf8;
    box-shadow: 0 8px 24px rgb(0 0 0 / 16%);
  }

  .gc-profile-photo-like {
    min-width: 64px;
    padding-inline: 13px;
  }

  .gc-profile-photo-like.is-liked {
    border-color: rgb(255 96 129 / 36%);
    background: rgb(235 74 105 / 14%);
    color: #ff6f91;
  }

  .gc-profile-photo-delete {
    color: #ff8495;
  }
}

@media (max-width: 360px) {
  .gc-profile-photo-footer {
    grid-template-columns: minmax(0, 1fr) auto;
    padding-left: max(12px, var(--gc-safe-left));
  }

  .gc-profile-photo-current {
    font-size: 11px;
  }

  .gc-profile-photo-like,
  .gc-profile-photo-delete {
    min-width: 44px;
    padding-inline: 10px;
  }
}

@media (orientation: landscape) and (max-height: 520px) {
  .gc-profile-photo-bar {
    min-height: calc(48px + var(--gc-safe-top));
    padding-top: calc(2px + var(--gc-safe-top));
    padding-bottom: 2px;
  }

  .gc-profile-photo-footer {
    min-height: calc(54px + var(--gc-safe-bottom));
    padding-top: 5px;
    padding-bottom: calc(5px + var(--gc-safe-bottom));
  }
}

@media (prefers-reduced-motion: reduce) {
  .gc-profile-photo-nav { backdrop-filter: none; }
}
