.gc-conference-invite-sheet { position: relative; width: min(440px, 100%); max-height: min(720px, 92dvh); display: grid; grid-template-rows: auto auto auto minmax(120px, 1fr) auto auto; gap: 12px; padding: 18px; overflow: hidden; border: 1px solid rgba(255,255,255,.14); border-radius: var(--gc-radius); color: #fff; background: #12221e; box-shadow: 0 28px 90px rgba(0,0,0,.48); }
