}
.gc-conference-settings-trigger .gc-icon { width: 20px; height: 20px; }
.gc-conference-tile {
  isolation: isolate;
  border-radius: var(--gc-radius-lg);
  background:
    radial-gradient(circle at 50% 28%, rgba(54, 190, 145, .17), transparent 44%),
    linear-gradient(155deg, rgba(20, 48, 41, .98), rgba(7, 20, 17, .99));
