  .gc-conference-stage {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(172px, 1fr) auto;
    gap: 8px;
    overflow: hidden;
  }
  .gc-conference-grid {
    grid-template-columns: 1fr;
    grid-auto-rows: minmax(172px, 1fr);
    gap: 8px;
    overflow: hidden auto;
    align-content: stretch;
  }
  .gc-conference-grid[data-count="1"] .gc-conference-tile {
    min-height: 172px;
  }
  .gc-conference-tile.is-placeholder {
    gap: 12px;
    padding: 18px;
  }
  .gc-conference-avatar {
    width: clamp(82px, 27vw, 108px);
    font-size: clamp(28px, 9vw, 38px);
    box-shadow: 0 18px 42px rgba(0, 0, 0, .24), 0 0 0 7px rgba(73, 232, 174, .05);
  }
  .gc-conference-tile.is-placeholder > .gc-conference-tile-name {
    max-width: min(86%, 260px);
    padding: 7px 12px;
    font-size: 16px;
    text-align: center;
  }
  .gc-conference-sidebar {
    max-height: min(220px, 27dvh);
    grid-template-rows: auto auto minmax(0, 1fr);
    border-radius: var(--gc-radius);
  }
  .gc-conference-sidebar h3 {
    padding: 10px 12px 8px;
    border-bottom: 0;
    font-size: 17px;
  }
  .gc-conference-invite-trigger {
    min-height: 43px;
    margin: 0 8px 4px;
    border-radius: var(--gc-radius-sm);
    font-size: 15px;
  }
  .gc-conference-participants { padding: 2px 6px 6px; }
  .gc-conference-person {
    grid-template-columns: 42px minmax(0, 1fr) auto auto;
    min-height: 54px;
    padding: 5px 7px;
    border-radius: var(--gc-radius-sm);
  }
  .gc-conference-person-avatar { width: 42px; height: 42px; }
  .gc-conference-person-copy strong { font-size: 15px; }
  .gc-conference-person-copy small { font-size: 12px; }
  .gc-conference-controls {
    display: grid;
    grid-template-columns: repeat(var(--gc-conference-control-columns, 4), minmax(0, 1fr));
    align-items: stretch;
    gap: 6px;
    overflow: visible;
    padding: 7px 6px calc(7px + env(safe-area-inset-bottom));
    border: 1px solid rgba(255, 255, 255, .085);
    border-radius: var(--gc-radius);
    background: rgba(10, 27, 23, .88);
    box-shadow: 0 -12px 35px rgba(0, 0, 0, .18), inset 0 1px 0 rgba(255, 255, 255, .035);
    backdrop-filter: blur(18px);
  }
  .gc-conference-controls[data-count="1"] { --gc-conference-control-columns: 1; }
  .gc-conference-controls[data-count="2"] { --gc-conference-control-columns: 2; }
  .gc-conference-controls[data-count="3"] { --gc-conference-control-columns: 3; }
  .gc-conference-controls[data-count="4"] { --gc-conference-control-columns: 4; }
  .gc-conference-controls[data-count="5"],
  .gc-conference-controls[data-count="6"] { --gc-conference-control-columns: 3; }
  .gc-conference-controls .gc-conference-control {
    min-width: 0;
    min-height: 64px;
    width: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 5px;
    padding: 7px 4px;
    border-radius: var(--gc-radius);
    scroll-snap-align: none;
  }
  .gc-conference-control .gc-icon { width: 22px; height: 22px; }
  .gc-conference-control span {
    max-width: 100%;
    overflow: visible;
    text-overflow: clip;
    white-space: normal;
    overflow-wrap: anywhere;
    font-size: 10px;
    line-height: 1.12;
    text-align: center;
  }
}

@media (max-width: 360px) and (orientation: portrait) {
  .gc-conference-stage { grid-template-rows: minmax(154px, 1fr) auto; }
  .gc-conference-grid { grid-auto-rows: minmax(154px, 1fr); }
  .gc-conference-sidebar { max-height: min(202px, 26dvh); }
  .gc-conference-controls { gap: 5px; padding-inline: 5px; }
  .gc-conference-controls .gc-conference-control { min-height: 61px; padding-inline: 2px; }
  .gc-conference-control span { font-size: 9px; }
}

/* Owner-only background music is a separate LiveKit audio publication. It lives above the control
   strip so changing the mix never hides microphone/camera/end actions on small screens. */
.gc-conference-control-area { min-width: 0; display: grid; gap: 7px; }
.gc-conference-music-input[hidden],
.gc-conference-music-panel[hidden] { display: none; }
.gc-conference-music-panel {
  min-width: 0;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) minmax(150px, 260px) auto;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid rgba(73, 232, 174, .28);
  border-radius: var(--gc-radius-sm);
  background: linear-gradient(110deg, rgba(32, 153, 112, .22), rgba(255, 255, 255, .055));
  animation: gc-conference-music-in .24s ease-out both;
}
.gc-conference-music-symbol { width: 38px; height: 38px; display: grid; place-items: center; border-radius: 50%; color: #052019; background: #71e7ba; }
.gc-conference-music-symbol .gc-icon { width: 18px; height: 18px; }
.gc-conference-music-copy { min-width: 0; display: grid; gap: 2px; }
.gc-conference-music-caption { color: rgba(255,255,255,.64); font-size: 11px; }
.gc-conference-music-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gc-conference-music-level { min-width: 0; display: grid; grid-template-columns: minmax(90px, 1fr) 44px; align-items: center; gap: 8px; }
.gc-conference-music-volume { width: 100%; accent-color: #67e5b5; }
.gc-conference-music-volume-value { color: #b8f7df; font-variant-numeric: tabular-nums; text-align: right; }
.gc-conference-music-stop { min-height: 40px; display: inline-flex; align-items: center; justify-content: center; gap: 7px; padding: 8px 12px; border: 1px solid rgba(255,255,255,.13); border-radius: var(--gc-radius-pill); color: #ffe1e1; background: rgba(177,47,55,.35); cursor: pointer; }
.gc-conference-music-stop:disabled { opacity: .45; cursor: not-allowed; }
.gc-conference-music-stop .gc-icon { width: 16px; height: 16px; }
@keyframes gc-conference-music-in { from { opacity: 0; transform: translateY(8px) scale(.985); } to { opacity: 1; transform: none; } }

@media (max-width: 620px) {
  .gc-conference-music-panel { grid-template-columns: 34px minmax(0, 1fr) auto; gap: 8px; padding: 8px; }
  .gc-conference-music-symbol { width: 34px; height: 34px; }
  .gc-conference-music-level { grid-column: 1 / -1; grid-row: 2; }
  .gc-conference-music-stop { min-width: 40px; width: 40px; padding: 0; }
  .gc-conference-music-stop span { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .gc-conference-music-panel { animation: none; }
}
