/* V214 — global conference invitations and 1:1 → group-call promotion. */
.gc-conference-incoming,
.gc-call-participant-picker {
  position: fixed;
  inset: 0;
  z-index: 2750;
  display: grid;
  place-items: center;
  padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
  background: rgba(3, 12, 10, .72);
  backdrop-filter: blur(18px) saturate(1.2);
}
.gc-conference-incoming-card,
.gc-call-participant-card {
  width: min(100%, 460px);
  border: 1px solid rgba(110, 236, 192, .24);
  border-radius: var(--gc-radius-lg);
  color: #f4fffb;
  background:
    radial-gradient(circle at 12% 0%, rgba(67, 225, 170, .20), transparent 38%),
    linear-gradient(155deg, rgba(21, 49, 42, .98), rgba(8, 22, 19, .99));
  box-shadow: 0 28px 90px rgba(0, 0, 0, .48);
}
.gc-conference-incoming-card { display: grid; justify-items: center; gap: 18px; padding: 30px; text-align: center; }
.gc-conference-incoming-avatar,
.gc-call-participant-avatar {
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 50%;
  background: var(--gc-avatar-bg, rgba(73, 232, 174, .18));
}
.gc-conference-incoming-avatar { width: 88px; height: 88px; font-size: 30px; box-shadow: 0 0 0 8px rgba(73, 232, 174, .08); }
.gc-conference-incoming-copy { display: grid; gap: 8px; }
.gc-conference-incoming-copy h2 { margin: 0; font-size: clamp(22px, 5vw, 28px); }
.gc-conference-incoming-lead,
.gc-conference-incoming-status { margin: 0; color: rgba(244, 255, 251, .70); }
.gc-conference-incoming-actions,
.gc-call-participant-footer { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; width: 100%; }
.gc-conference-incoming-actions button,
.gc-call-participant-footer button {
  min-height: 50px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: var(--gc-radius);
  border: 1px solid rgba(255, 255, 255, .12);
  color: #fff;
  cursor: pointer;
}
.gc-conference-incoming-decline,
.gc-call-participant-cancel { background: rgba(255, 255, 255, .08); }
.gc-conference-incoming-accept,
.gc-call-participant-submit { background: linear-gradient(135deg, #2ebd86, #168a72); }
.gc-conference-incoming-actions button:disabled,
.gc-call-participant-footer button:disabled { opacity: .55; cursor: default; }
.gc-conference-incoming-actions .gc-icon,
.gc-call-participant-footer .gc-icon { width: 20px; height: 20px; }

.gc-call-participant-card { max-height: min(760px, calc(100dvh - 36px)); display: grid; grid-template-rows: auto auto auto minmax(120px, 1fr) auto auto; gap: 12px; padding: 20px; overflow: hidden; }
.gc-call-participant-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
.gc-call-participant-header h2,
.gc-call-participant-header p { margin: 0; }
.gc-call-participant-header p { margin-top: 5px; color: rgba(244, 255, 251, .63); font-size: 14px; }
.gc-call-participant-close { flex: 0 0 auto; width: 42px; height: 42px; display: grid; place-items: center; border: 0; border-radius: var(--gc-radius-sm); color: #fff; background: rgba(255,255,255,.08); cursor: pointer; }
.gc-call-participant-current,
.gc-call-participant-row { display: grid; grid-template-columns: 44px minmax(0,1fr) auto; align-items: center; gap: 11px; }
.gc-call-participant-current { padding: 10px; border: 1px solid rgba(73,232,174,.18); border-radius: var(--gc-radius); background: rgba(73,232,174,.08); }
.gc-call-participant-current > span:last-child,
.gc-call-participant-copy { min-width: 0; display: grid; }
.gc-call-participant-current small,
.gc-call-participant-copy small { color: rgba(244,255,251,.58); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gc-call-participant-avatar { width: 44px; height: 44px; }
.gc-call-participant-search { min-height: 46px; width: 100%; padding: 0 14px; border: 1px solid rgba(255,255,255,.12); border-radius: var(--gc-radius); color: #fff; background: rgba(255,255,255,.07); outline: none; }
.gc-call-participant-search:focus { border-color: rgba(73,232,174,.65); box-shadow: 0 0 0 3px rgba(73,232,174,.10); }
.gc-call-participant-list { min-height: 0; overflow: auto; display: grid; align-content: start; gap: 4px; padding-right: 3px; }
.gc-call-participant-row { min-height: 60px; padding: 8px; border-radius: var(--gc-radius); cursor: pointer; }
.gc-call-participant-row:hover { background: rgba(255,255,255,.06); }
.gc-call-participant-row input { width: 22px; height: 22px; accent-color: #2ebd86; }
.gc-call-participant-status { min-height: 20px; margin: 0; color: rgba(244,255,251,.67); font-size: 14px; }

@media (max-width: 560px) {
  .gc-conference-incoming,
  .gc-call-participant-picker { place-items: end center; padding: 10px max(10px, env(safe-area-inset-right)) max(10px, env(safe-area-inset-bottom)) max(10px, env(safe-area-inset-left)); }
  .gc-conference-incoming-card,
  .gc-call-participant-card { width: 100%; border-radius: var(--gc-radius-lg); }
  .gc-call-participant-card { max-height: min(82dvh, 720px); }
}
@media (prefers-reduced-motion: reduce) {
  .gc-conference-incoming,
  .gc-call-participant-picker { backdrop-filter: none; }
}
